import { Console, Data, Effect } from "effect"
import { CliError, Command } from "effect/unstable/cli"

const profiles: Readonly<Record<string, string>> = {
  development: "https://api.dev.example.net",
  production: "https://api.example.net"
}

export class UnknownProfile extends Data.TaggedError("UnknownProfile")<{
  readonly profile: string
}> {
  override get message(): string {
    return `Profile "${this.profile}" is not configured.`
  }

  get [CliError.userMessage](): string {
    return this.message
  }
}

export const showEndpoint = (profile: string) =>
  Effect.gen(function*() {
    const endpoint = profiles[profile]
    if (endpoint === undefined) {
      return yield* Effect.fail(new UnknownProfile({ profile }))
    }
    yield* Console.log(endpoint)
  })

export const endpointCommand = Command.make("endpoint", {}, () =>
  showEndpoint(process.env.CLI_PROFILE ?? "development").pipe(
    Effect.catch((error) => {
      if (error instanceof UnknownProfile) {
        return Console.log(
          `Choose a configured profile with CLI_PROFILE: ${Object.keys(profiles).join(", ")}`
        )
      }
      return Effect.fail(error)
    })
  )
)
